#!/usr/bin/env Rscript

suppressPackageStartupMessages({ library(optparse); library(jsonlite); library(ggplot2) })
`%||%` <- function(x, y) if (is.null(x) || !length(x)) y else x
op <- parse_args(OptionParser(option_list = list(make_option('--input', type='character'), make_option('--params', type='character'), make_option('--output', type='character'))))
out <- op$output %||% getwd(); dir.create(out, recursive=TRUE, showWarnings=FALSE)
unlink(file.path(out, c('result.svg','result.pdf','result.png','result.html','figure.json','histogram_data_used.csv','selected_rows.csv','error.json')), force=TRUE)
logmsg <- function(x) { line <- sprintf('[%s] %s\n', format(Sys.time(), '%F %T'), x); cat(line); cat(line, file=file.path(out,'run.log'), append=TRUE) }
fail <- function(message, detail='', suggestion='Check input columns and params.json.') { writeLines(toJSON(list(error=message, detail=detail, suggestion=suggestion), auto_unbox=TRUE, pretty=TRUE), file.path(out,'error.json')); quit(status=1) }

main <- function() {
  if (is.null(op$input) || !file.exists(op$input)) fail('Input file not found', as.character(op$input))
  p <- if (!is.null(op$params) && file.exists(op$params)) fromJSON(op$params, simplifyVector=FALSE) else list()
  val <- function(n, d=NULL, aliases=character()) { x <- p[[n]]; if (is.null(x)) for (g in names(p)) if (is.list(p[[g]]) && !is.null(p[[g]][[n]])) { x <- p[[g]][[n]]; break }; if (is.null(x)) for (a in aliases) if (!is.null(p[[a]])) { x <- p[[a]]; break }; x %||% d }
  vec <- function(x) { if (is.null(x)) return(character()); x <- unlist(x, use.names=FALSE); if (length(x)==1 && grepl(',',x,fixed=TRUE)) x <- strsplit(x,',',fixed=TRUE)[[1]]; trimws(as.character(x)) }
  num <- function(n,d=0) { x <- suppressWarnings(as.numeric(unlist(val(n,d))[1])); ifelse(is.finite(x),x,d) }
  boo <- function(n,d=FALSE) { x <- val(n,d); if (is.logical(x)) isTRUE(x[1]) else tolower(as.character(x[1])) %in% c('true','t','yes','y','1','on') }
  readtab <- function(x) if (tolower(tools::file_ext(x)) %in% c('tsv','txt')) read.delim(x,check.names=FALSE,stringsAsFactors=FALSE) else read.csv(x,check.names=FALSE,stringsAsFactors=FALSE)
  d0 <- readtab(op$input); cn <- names(d0); low <- tolower(cn); findcol <- function(x, defaults=character()) { h <- match(tolower(c(x,defaults)),low); h <- h[!is.na(h)]; if(length(h)) cn[h[1]] else NULL }
  mode <- tolower(as.character(val('input_mode','auto'))); if (!mode %in% c('auto','wide','long')) fail('Unsupported input_mode',mode,'Use auto, wide, or long.')
  vc <- findcol(val('value_column',NULL,c('value_col')),c('value','measurement','score')); gc <- findcol(val('group_column',NULL,c('group_col')),c('group','condition','class')); idc <- findcol(val('id_column',NULL,c('sample_column','sample_id_column')),c('id','sample','sample_id','observation'))
  is_long <- mode=='long' || (mode=='auto' && !is.null(vc) && !is.null(gc)); if (mode=='long' && (is.null(vc)||is.null(gc))) fail('Long input requires value_column and group_column')
  row_keep <- rep(TRUE,nrow(d0)); rows_inc <- vec(val('rows_include')); rows_exc <- vec(val('rows_exclude')); ids <- if(is.null(idc)) as.character(seq_len(nrow(d0))) else as.character(d0[[idc]])
  if(length(rows_inc)) row_keep <- seq_len(nrow(d0)) %in% suppressWarnings(as.integer(rows_inc)) | ids %in% rows_inc
  if(length(rows_exc)) row_keep <- row_keep & !(seq_len(nrow(d0)) %in% suppressWarnings(as.integer(rows_exc)) | ids %in% rows_exc)
  d <- d0[row_keep,,drop=FALSE]; write.csv(d,file.path(out,'selected_rows.csv'),row.names=FALSE)
  if (is_long) {
    z <- data.frame(id=if(is.null(idc)) as.character(seq_len(nrow(d))) else as.character(d[[idc]]), group=as.character(d[[gc]]), value=suppressWarnings(as.numeric(d[[vc]])), stringsAsFactors=FALSE)
  } else {
    if (is.null(idc) && !is.numeric(d[[1]])) idc <- cn[1]
    candidates <- if(is.null(idc)) cn else setdiff(cn,idc); numeric_cols <- candidates[vapply(d[candidates],function(x) any(is.finite(suppressWarnings(as.numeric(x)))),logical(1))]
    if(!length(numeric_cols)) fail('Wide input has no numeric group columns','','Use an optional id column followed by numeric columns.')
    z <- do.call(rbind,lapply(numeric_cols,function(g) data.frame(id=if(is.null(idc)) as.character(seq_len(nrow(d))) else as.character(d[[idc]]),group=g,value=suppressWarnings(as.numeric(d[[g]])),stringsAsFactors=FALSE)))
  }
  z <- z[is.finite(z$value) & !is.na(z$group) & nzchar(z$group),,drop=FALSE]; if(!nrow(z)) fail('No valid numeric rows remain')
  inc <- vec(val('groups_include')); exc <- vec(val('groups_exclude')); if(length(inc)) z <- z[z$group %in% inc,,drop=FALSE]; if(length(exc)) z <- z[!z$group %in% exc,,drop=FALSE]; if(!nrow(z)) fail('No groups remain after filtering')
  groups <- unique(z$group); requested <- vec(val('group_order')); if(length(requested)) groups <- unique(c(requested,groups)); groups <- groups[groups %in% unique(z$group)]; z$group <- factor(z$group,levels=groups)
  write.csv(z[,c('id','group','value')],file.path(out,'histogram_data_used.csv'),row.names=FALSE)
  logmsg(sprintf('Using %d values across %d groups (%s input)',nrow(z),length(groups),mode))

  xr <- suppressWarnings(as.numeric(unlist(val('x_limits',NULL)))); xr <- xr[is.finite(xr)]; data_range <- range(z$value); if(length(xr)!=2) xr <- data_range; if(xr[1]>xr[2]) xr <- rev(xr); if(xr[1]==xr[2]) xr <- xr+c(-.5,.5)
  method <- tolower(as.character(val('bin_method','fixed'))); bins_req <- max(1,as.integer(num('bins',40))); bw <- num('binwidth',NA_real_); boundary <- num('boundary',NA_real_); center <- num('center',NA_real_)
  if(method=='pretty') { breaks <- pretty(data_range,n=bins_req); breaks <- sort(unique(breaks)); bw <- median(diff(breaks)) } else { if(is.finite(bw) && bw>0) { anchor <- if(is.finite(center)) center-bw/2 else if(is.finite(boundary)) boundary else data_range[1]; lo <- anchor+floor((data_range[1]-anchor)/bw)*bw; hi <- anchor+ceiling((data_range[2]-anchor)/bw)*bw; breaks <- seq(lo,hi+bw*.001,by=bw) } else { bw <- diff(data_range)/bins_req; if(!is.finite(bw)||bw<=0) bw <- 1; anchor <- if(is.finite(center)) center-bw/2 else if(is.finite(boundary)) boundary else data_range[1]; lo <- anchor+floor((data_range[1]-anchor)/bw)*bw; hi <- anchor+ceiling((data_range[2]-anchor)/bw)*bw; breaks <- seq(lo,hi+bw*.001,by=bw) } }
  if(length(breaks)<2) breaks <- c(data_range[1]-bw/2,data_range[2]+bw/2); bw <- median(diff(breaks)); closed <- tolower(as.character(val('closed','right'))); bin_index <- findInterval(z$value,breaks,rightmost.closed=closed=='right',left.open=closed=='left'); bin_index[bin_index<1] <- 1; bin_index[bin_index>=length(breaks)] <- length(breaks)-1
  rows <- list(); k <- 0
  for(g in groups) for(i in seq_len(length(breaks)-1)) { v <- z$value[z$group==g & bin_index[z$group==g]==i]; k <- k+1; rows[[k]] <- data.frame(group=as.character(g),bin_start=breaks[i],bin_end=breaks[i+1],count=length(v),value_min=if(length(v))min(v) else NA_real_,value_max=if(length(v))max(v) else NA_real_,stringsAsFactors=FALSE) }
  bd <- do.call(rbind,rows); group_totals <- tapply(bd$count,bd$group,sum); bd$density <- bd$count/(unname(group_totals[bd$group])*bw); bd$frequency <- bd$count/bw
  stat <- tolower(as.character(val('stat','count'))); if(!stat %in% c('count','density','frequency')) fail('Unsupported stat',stat,'Use count, density, or frequency.')
  bd$raw_y <- bd[[stat]]; pos <- tolower(as.character(val('position','identity'))); if(!pos %in% c('identity','stack','fill')) fail('Unsupported position',pos)
  bd$ymin <- 0; bd$ymax <- bd$raw_y
  if(pos=='stack') for(i in seq_len(length(breaks)-1)) { ix <- which(abs(bd$bin_start-breaks[i])<.Machine$double.eps); bd$ymin[ix] <- c(0,cumsum(bd$raw_y[ix])[-length(ix)]); bd$ymax[ix] <- cumsum(bd$raw_y[ix]) }
  if(pos=='fill') { for(i in seq_len(length(breaks)-1)) { ix <- which(abs(bd$bin_start-breaks[i])<.Machine$double.eps); s <- sum(bd$raw_y[ix]); if(s>0) bd$ymax[ix] <- bd$raw_y[ix]/s else bd$ymax[ix] <- 0 }; bd$raw_y <- bd$ymax }
  tipcols <- vec(val('tooltip_columns',c('group','bin_start','bin_end','count','value_min','value_max'))); tipcols <- intersect(tipcols,names(bd)); bd$text <- vapply(seq_len(nrow(bd)),function(i) paste(sprintf('%s: %s',tipcols, vapply(tipcols,function(n) { x<-bd[[n]][i]; if(is.na(x)) 'NA' else if(is.numeric(x)) format(signif(x,6),trim=TRUE,scientific=FALSE) else as.character(x) },character(1))),collapse='<br>'),character(1))
  fill_default <- c('#4E79A7','#F28E2B','#E15759','#59A14F','#B07AA1','#76B7B2'); cols <- unlist(val('fill_colors',NULL),use.names=TRUE); if(!length(cols)) cols <- fill_default; fill <- setNames(rep(cols,length.out=length(groups)),groups); if(!is.null(names(cols))) for(g in groups) if(g %in% names(cols)) fill[g] <- cols[[g]]
  outlines <- unlist(val('outline_colors',NULL),use.names=TRUE); if(!length(outlines)) outlines <- setNames(rep('#333333',length(groups)),groups); if(is.null(names(outlines))) outlines <- setNames(rep(outlines,length.out=length(groups)),groups); outlines <- setNames(grDevices::adjustcolor(as.character(outlines),alpha.f=num('outline_alpha',1)),names(outlines))
  q <- ggplot(bd,aes(xmin=bin_start,xmax=bin_end,ymin=ymin,ymax=ymax,fill=group,colour=group,text=text)) + geom_rect(alpha=num('alpha',.55),linewidth=num('outline_width',.35),linejoin='mitre') + scale_fill_manual(values=fill,drop=FALSE) + scale_colour_manual(values=outlines,drop=FALSE) + scale_x_continuous(limits=if(length(xr)==2) xr else NULL,breaks=if(length(vec(val('x_breaks')))) suppressWarnings(as.numeric(vec(val('x_breaks')))) else waiver(),expand=c(0,0)) + scale_y_continuous(limits={y<-suppressWarnings(as.numeric(unlist(val('y_limits',NULL))));if(length(y)==2)y else NULL},breaks={y<-suppressWarnings(as.numeric(unlist(val('y_breaks',NULL))));if(length(y))y else waiver()}) + labs(x=val('xlab','Value'),y=val('ylab',if(stat=='count')'Count' else stat),title=val('title',NULL),subtitle=val('subtitle',NULL),caption=val('caption',NULL),fill=val('legend_title','Group'),colour=val('legend_title','Group')) + theme_minimal(base_size=num('base_size',11),base_family=val('font_family','sans')) + theme(panel.background=element_rect(fill=val('panel_background','#FFFFFF'),colour=NA),plot.background=element_rect(fill=val('plot_background','#FFFFFF'),colour=NA),panel.grid=if(boo('grid_show',TRUE))element_line(colour=val('grid_color','#E6E6E6'),linewidth=num('grid_width',.35)) else element_blank(),legend.position=if(boo('legend_show',TRUE))val('legend_position','bottom') else 'none',legend.text=element_text(size=num('legend_text_size',9)),legend.title=element_text(size=num('legend_text_size',9)),legend.direction='horizontal')
  if(as.integer(num('legend_ncol',1))>1) q <- q+guides(fill=guide_legend(ncol=as.integer(num('legend_ncol',1))),colour='none') else q <- q+guides(colour='none'); if(boo('flip',FALSE)) q <- q+coord_flip()
  w<-num('width',10); h<-num('height',6); dpi<-as.integer(num('dpi',300)); formats<-tolower(vec(val('export_formats',c('svg','pdf','png','html')))); if('svg'%in%formats)ggsave(file.path(out,'result.svg'),q,width=w,height=h,units='in',dpi=dpi); if('pdf'%in%formats)ggsave(file.path(out,'result.pdf'),q,width=w,height=h,units='in'); if('png'%in%formats)ggsave(file.path(out,'result.png'),q,width=w,height=h,units='in',dpi=dpi)
  interactive <- boo('interactive',TRUE); if(interactive) { if(!requireNamespace('plotly',quietly=TRUE)||!requireNamespace('htmlwidgets',quietly=TRUE))fail('plotly / htmlwidgets not available','','Install plotly and htmlwidgets, or set interactive=false.'); tryCatch({ pl<-plotly::ggplotly(q,tooltip='text'); remove_buttons<-unique(c(if(!boo('pan',TRUE))'pan2d' else character(),if(!boo('zoom',TRUE))c('zoom2d','zoomIn2d','zoomOut2d') else character(),if(!boo('reset_view',TRUE))c('autoScale2d','resetScale2d') else character())); pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),doubleClick=if(boo('reset_view',TRUE))'reset' else FALSE,modeBarButtonsToAdd=if(boo('lasso_select',FALSE)||boo('selectable',FALSE))c('lasso2d','select2d') else character(),modeBarButtonsToRemove=remove_buttons); htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE); logmsg('Wrote result.html (interactive Plotly)') },error=function(e)fail('Interactive HTML generation failed',conditionMessage(e))) } else writeLines('<html><body><p>Interactive Plotly output is disabled.</p></body></html>',file.path(out,'result.html'))
  per <- lapply(groups,function(g){v<-z$value[z$group==g];list(n=length(v),mean=round(mean(v),6),median=round(median(v),6),sd=round(sd(v),6),min=round(min(v),6),max=round(max(v),6))}); names(per)<-groups
  fig<-list(plugin='interactive_histogram_plot',title=val('title',NULL),n_groups=length(groups),groups=as.character(groups),n_values=nrow(z),stat=stat,bins=length(breaks)-1,binwidth=round(bw,12),x_range=round(range(breaks),12),per_group_summary=per,outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','histogram_data_used.csv','selected_rows.csv')); writeLines(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json')); unlink(file.path(out,'error.json'),force=TRUE); logmsg('Finished interactive_histogram_plot')
}
tryCatch(main(),error=function(e) fail('Plot generation failed',conditionMessage(e),'Check input columns, params.json, and installed R packages.'))
